import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type HeartThoughtComponentProps = Record<string, any>;

const HeartThoughtComponent: React.FC<HeartThoughtComponentProps> = ({
  backgroundColor = "#080b13",
  transparentBackground = false,
  durationInSeconds = 8,
  heartColor = "#ff3366",
  thoughtFormColor = "#44bbff",
  glowColor = "#88ccff",
  pathColor = "#ffffff",
  heartSize = 60,
  thoughtFormSize = 220,
  mainMessage = "A warm thought sent across the void.",
}) => {
  useFontLoader(["Inter", "Playfair Display"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Dynamic Timeline
  const totalFrames = durationInSeconds * fps;
  const spawnFrame = totalFrames * 0.1;
  const travelStartFrame = totalFrames * 0.2;
  const travelEndFrame = totalFrames * 0.6;
  
  // Spatial Coordinates (Responsive)
  const startX = width * 0.2;
  const startY = height * 0.7;
  const endX = width * 0.8;
  const endY = height * 0.35;
  
  // Bezier Control Point (High up to create a sweeping arc)
  const cx = width * 0.45;
  const cy = height * -0.1;

  // Animation Progress
  const heartEntryScale = spring({
    frame: Math.max(0, frame - spawnFrame),
    fps,
    config: { damping: 12 },
  });

  const travelProgress = interpolate(
    frame,
    [travelStartFrame, travelEndFrame],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.quad),
    }
  );

  // Bezier Path Calculations for Heart Position
  const bezierX = (t: number) =>
    Math.pow(1 - t, 2) * startX +
    2 * (1 - t) * t * cx +
    Math.pow(t, 2) * endX;

  const bezierY = (t: number) =>
    Math.pow(1 - t, 2) * startY +
    2 * (1 - t) * t * cy +
    Math.pow(t, 2) * endY;

  const currentHeartX = bezierX(travelProgress);
  const currentHeartY = bezierY(travelProgress);

  // Derivative calculation to find the tangent angle for natural rotation
  const getTangentAngle = (t: number) => {
    const dx = 2 * (1 - t) * (cx - startX) + 2 * t * (endX - cx);
    const dy = 2 * (1 - t) * (cy - startY) + 2 * t * (endY - cy);
    return Math.atan2(dy, dx) * (180 / Math.PI);
  };

  // Heart naturally points down (90deg), so add 90 to face the direction of travel
  const heartRotation = getTangentAngle(travelProgress) + 90;

  // Impact Logic
  const impactFrame = frame - travelEndFrame;
  const isAbsorbed = frame >= travelEndFrame;
  
  const heartOpacity = interpolate(travelProgress, [0.95, 1], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const impactPop = spring({
    frame: Math.max(0, impactFrame),
    fps,
    config: { damping: 12, mass: 0.5, stiffness: 180 },
  });

  // Ripple Animation
  const rippleScale = interpolate(impactFrame, [0, 45], [1, 4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const rippleOpacity = interpolate(impactFrame, [0, 15, 45], [0, 0.6, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Thought Form Organic Ambient Motion
  const ambientScale = interpolate(Math.sin(frame / 20), [-1, 1], [0.96, 1.04]);
  const finalOrbScale = (1 + impactPop * 0.3) * ambientScale;

  // Ethereal Orbits for Thought Form
  const orb1OffsetX = Math.cos(frame / 35) * (thoughtFormSize * 0.1);
  const orb1OffsetY = Math.sin(frame / 35) * (thoughtFormSize * 0.1);
  const orb2OffsetX = Math.sin(frame / 25) * -(thoughtFormSize * 0.15);
  const orb2OffsetY = Math.cos(frame / 25) * (thoughtFormSize * 0.15);

  // Text Animation
  const textOpacity = interpolate(
    frame,
    [travelEndFrame + 10, travelEndFrame + 40],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const textYOffset = interpolate(
    frame,
    [travelEndFrame + 10, travelEndFrame + 40],
    [20, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Dynamic Trail Path */}
      <svg
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          transition: "none",
          pointerEvents: "none",
        }}
      >
        <path
          d={`M ${startX} ${startY} Q ${cx} ${cy} ${endX} ${endY}`}
          fill="none"
          stroke={pathColor}
          strokeWidth="4"
          strokeLinecap="round"
          pathLength="100"
          strokeDasharray="100"
          strokeDashoffset={100 - travelProgress * 100}
          opacity={interpolate(travelProgress, [0.8, 1], [0.4, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          })}
          style={{ transition: "none" }}
        />
        
        {/* Expanding Ripple on Impact */}
        {impactFrame >= 0 && (
          <circle
            cx={endX}
            cy={endY}
            r={thoughtFormSize * 0.4 * rippleScale}
            fill="none"
            stroke={glowColor}
            strokeWidth={4}
            opacity={rippleOpacity}
            style={{ transition: "none" }}
          />
        )}
      </svg>

      {/* Abstract Thought Form */}
      <div
        style={{
          position: "absolute",
          left: endX,
          top: endY,
          width: thoughtFormSize,
          height: thoughtFormSize,
          transform: `translate(-50%, -50%) scale(${finalOrbScale})`,
          transition: "none",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* Glow Base */}
        <div
          style={{
            position: "absolute",
            width: "140%",
            height: "140%",
            backgroundColor: glowColor,
            borderRadius: "50%",
            filter: "blur(40px)",
            opacity: 0.3 + impactPop * 0.3,
            transition: "none",
          }}
        />
        
        {/* Core Orbs creating the "Form" */}
        <div
          style={{
            position: "absolute",
            width: "80%",
            height: "80%",
            backgroundColor: thoughtFormColor,
            borderRadius: "50%",
            filter: "blur(12px)",
            opacity: 0.8,
            transition: "none",
          }}
        />
        <div
          style={{
            position: "absolute",
            width: "60%",
            height: "60%",
            backgroundColor: glowColor,
            borderRadius: "50%",
            filter: "blur(8px)",
            opacity: 0.9,
            transform: `translate(${orb1OffsetX}px, ${orb1OffsetY}px)`,
            transition: "none",
          }}
        />
        <div
          style={{
            position: "absolute",
            width: "50%",
            height: "50%",
            backgroundColor: "#ffffff",
            borderRadius: "50%",
            filter: "blur(10px)",
            opacity: 0.7 + impactPop * 0.3,
            transform: `translate(${orb2OffsetX}px, ${orb2OffsetY}px)`,
            transition: "none",
          }}
        />
      </div>

      {/* The Heart */}
      {!isAbsorbed && (
        <div
          style={{
            position: "absolute",
            left: currentHeartX,
            top: currentHeartY,
            width: heartSize,
            height: heartSize,
            transform: `translate(-50%, -50%) rotate(${heartRotation}deg) scale(${heartEntryScale})`,
            opacity: heartOpacity,
            transition: "none",
            filter: `drop-shadow(0px 0px ${heartSize * 0.2}px ${heartColor}88)`,
          }}
        >
          <svg
            viewBox="0 0 24 24"
            fill={heartColor}
            width="100%"
            height="100%"
            style={{ transition: "none" }}
          >
            <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
          </svg>
        </div>
      )}

      {/* Message Text */}
      <div
        style={{
          position: "absolute",
          bottom: "15%",
          width: "100%",
          textAlign: "center",
          opacity: textOpacity,
          transform: `translateY(${textYOffset}px)`,
          transition: "none",
        }}
      >
        <h2
          style={{
            fontFamily: "Playfair Display, serif",
            fontSize: height * 0.05,
            color: "#ffffff",
            margin: 0,
            fontWeight: 600,
            textShadow: `0px 4px 16px ${glowColor}66`,
            transition: "none",
          }}
        >
          {mainMessage}
        </h2>
      </div>
    </AbsoluteFill>
  );
};

export default HeartThoughtComponent;